"""Reviewed Zoho Lead fields retained by the Hub without live synchronization."""

from dataclasses import dataclass


@dataclass(frozen=True)
class HubLeadField:
    key: str
    label: str
    api_name: str
    display_type: str
    required: bool = False
    read_only: bool = False
    options: tuple[tuple[str, str], ...] = ()


@dataclass(frozen=True)
class HubLeadSubform:
    key: str
    label: str
    parent_api_name: str
    module: str
    fields: tuple[HubLeadField, ...]


